// The API's version: the major version times 65536, plus the minor version.
#define FIR_API_VERSION (1 << 16)

// No id: what a call returns when it fails.
#define FIR_INVALID UINT32_MAX

// The interpreter's default step limit, as `fir run` uses.
#define FIR_DEFAULT_FUEL 1000000

// Builds one function of a module.
typedef struct FirBuilder FirBuilder;

// A module being built, with everything made in it.
typedef struct FirModule FirModule;

// What a call that doesn't return an id reports.
typedef uint32_t FirStatus;

// One entry of a data layout's integer alignments.
typedef struct FirIntAlign {
  // In bits.
  uint32_t width;
  // In bytes.
  uint32_t align;
} FirIntAlign;

// A module's layer, for `fir_module_set_layer`.
typedef uint32_t FirLayer;

// An object format and its assembler conventions, for `fir_module_compile`.
typedef uint32_t FirOs;

// A type: a value type (`fir_type_int`, `fir_type_byte`, `FIR_TYPE_PTR`, `FIR_TYPE_SLICE`), or a
// struct, array, union, or function type of a module.
typedef uint32_t FirType;

// A struct's layout (`Policy`).
typedef uint32_t FirPolicy;

// A function of a module, defined in it or external.
typedef uint32_t FirFunc;

// What an external function may do (`ExtEffect`).
typedef uint32_t FirEffect;

// How much a fact is trusted (`Trust`).
typedef uint32_t FirTrust;

// A global of a module.
typedef uint32_t FirGlobal;

// A global's initializer, made in a module for `fir_global_declare`.
typedef uint32_t FirInit;

// A value or a hole of the function being built.
typedef uint32_t FirValue;

// A region of the function being built; also a block of `cf.blocks`.
typedef uint32_t FirRegion;

// An op of the function being built.
typedef uint32_t FirOp;

// A fact's kind (`Fact`).
typedef uint32_t FirFactKind;

// A fact on a value: a `FIR_FACT_*` kind, a `FIR_TRUST_*` tag, and its numbers (the bounds of a
// range; `lo` is the alignment of `FIR_FACT_ALIGN`).
typedef struct FirFact {
  FirFactKind kind;
  FirTrust trust;
  int64_t lo;
  int64_t hi;
} FirFact;

// `int.add`, `int.sub`, `int.mul` (`ArithOp`).
typedef uint32_t FirArithOp;

// Overflow behavior of `int.add`, `int.sub`, `int.mul` (`Ovf`).
typedef uint32_t FirOvf;

// `int.and`, `int.or`, `int.xor` (`BitOp`).
typedef uint32_t FirBitOp;

// `int.div.s`, `int.div.u`, `int.rem.s`, `int.rem.u` (`DivOp`).
typedef uint32_t FirDivOp;

// An edge case of division and remainder (`Edge`).
typedef uint32_t FirEdge;

// `int.shl`, `int.shr.u`, `int.shr.s` (`ShiftOp`).
typedef uint32_t FirShiftOp;

// Shifts by at least the width (`ShiftEdge`).
typedef uint32_t FirShiftEdge;

// A comparison (`Pred`).
typedef uint32_t FirPred;

// `int.trunc` losing bits (`TruncMode`).
typedef uint32_t FirTruncMode;

// What `mem.alloc` does when allocation fails (`AllocFail`).
typedef uint32_t FirAllocFail;

// A branch target: a block, and the arguments for its parameters.
typedef struct FirTarget {
  FirRegion block;
  const FirValue *args;
  size_t nargs;
} FirTarget;

// One case of `cf.switch`.
typedef struct FirCase {
  int64_t key;
  struct FirTarget target;
} FirCase;

// Why `cf.check` and `aarch64.trap` trap (`TrapReason`).
typedef uint32_t FirTrapReason;

// `aarch64.add`, `aarch64.sub`, … on three registers (`AluOp`).
typedef uint32_t FirAluOp;

// The operation size of an `aarch64.*` op (`Sf`): 32 or 64 bits.
typedef uint32_t FirSf;

// A register of an `aarch64.*` op: `x0`…`x30` are 0…30, then `FIR_REG_SP` and `FIR_REG_XZR`;
// the virtual register `vN` is `FIR_REG_V0 + N`.
typedef uint32_t FirReg;

// `aarch64.add.imm`, … with an immediate (`AluImmOp`).
typedef uint32_t FirAluImmOp;

// `aarch64.lsl.imm`, `aarch64.lsr.imm`, `aarch64.asr.imm` (`ShiftImmOp`).
typedef uint32_t FirShiftImmOp;

// `aarch64.movz`, `aarch64.movn`, `aarch64.movk` (`MovOp`).
typedef uint32_t FirMovOp;

// `aarch64.csel`, `aarch64.csinc`, `aarch64.csinv`, `aarch64.csneg` (`CselOp`).
typedef uint32_t FirCselOp;

// An AArch64 condition (`Cond`).
typedef uint32_t FirCond;

// The access size of `aarch64.ldr` and `aarch64.str`: 1, 2, 4, or 8 bytes (`MemSize`).
typedef uint32_t FirMemSize;

